const standard = (id, url) => ({ id, url });
const fixture = (id, path) => ({ id, path });

function entry(adapter, rule) {
  return {
    adapter,
    maturity: 'stable',
    revision: '1',
    frameworks: [],
    alternatives: [],
    userDecisions: [],
    ...rule,
  };
}

