function opengrepFlow(language, riskName) {
  const risk = OPENGREP_FLOW_RISKS[riskName];
  const js = language === 'javascript';
  const languageId = js ? 'js' : 'python';
  const languageLabel = js ? 'JavaScript and TypeScript' : 'Python';
  const externalLanguage = js ? 'javascript' : 'python';
  return entry(opengrep, {
    id: `opengrep-${languageId}-request-${risk.suffix}-flow`, revision: `1-${OPENGREP_RULESET_SHA}`,
    kind: 'risk_detection', family: risk.family,
    languages: js ? ['javascript', 'typescript'] : ['python'], frameworks: js ? ['Express'] : ['Flask'],
    domain: 'security_exposure', severity: risk.severity, defaultState: 'suspected',
    rationale: `request_data_reaches_${risk.suffix}_sink`, technicalTerm: risk.technicalTerm,
    plainLanguage: risk.plainLanguage,
    consequence: risk.consequence,
    confidenceBoundary: `The pinned local taint rule observed a same-file ${languageLabel} request-source-to-${risk.suffix} sink path. It did not prove framework routing, validation bypass, runtime reachability, exploitability or a deployed endpoint.`,
    applicability: `${languageLabel} scanned by caller-installed Opengrep 1.27.0 with the bundled local ruleset.`,
    detection: { type: 'external_taint_adapter', engine: 'opengrep', rulesetSha256: OPENGREP_RULESET_SHA, externalRuleId: `webapp-security.${externalLanguage}.request-to-${risk.externalSuffix}`, interfile: false },
    standards: [standard(risk.cwe, `https://cwe.mitre.org/data/definitions/${risk.cwe.slice(4)}.html`), standard(risk.owasp, risk.owaspUrl)],
    falsePositiveCauses: ['The route is unreachable or the request value is replaced by a strict fixed allowlist before the sink.', risk.falsePositive],
    proposal: { status: 'review_required', summary: risk.proposal },
    alternatives: [risk.alternative], proposalRisks: [risk.risk], sideEffects: [risk.sideEffect],
    securityRetest: risk.securityRetest, functionalRetest: risk.functionalRetest, rollback: risk.rollback,
    userDecisions: [risk.decision],
    helpUri: 'https://github.com/parousia8888/web-app-security-skill/blob/main/docs/adapter-protocol.md',
    fixtures: {
      positive: [fixture(`opengrep-${languageId}-${risk.suffix}-positive`, `test/fixtures/opengrep-rules/vulnerable.${js ? 'js' : 'py'}`)],
      negative: [fixture(`opengrep-${languageId}-${risk.suffix}-safe`, `test/fixtures/opengrep-rules/safe.${js ? 'js' : 'py'}`)],
    },
  });
}

